<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import { listarTareas, recibirTarea } from '@/modules/evan/catastro/services/tareas'
import type { Option, Tarea } from '@/modules/evan/catastro/interfaces/tareas.interface'
const rows=ref<Tarea[]>([]),districts=ref<Option[]>([]),types=ref<Option[]>([]),total=ref(0),lastPage=ref(1),loading=ref(false),receiving=ref(0),error=ref(''),success=ref('');const filters=reactive({criterio:'',distrito_id:0,tipo_atencion_id:0,page:1});async function load(p=1){filters.page=p;loading.value=true;try{const r=await listarTareas(filters,'medicion');rows.value=r.data;total.value=r.total;lastPage.value=r.last_page;districts.value=r.distritos;types.value=r.tipos_atencion}catch(e){error.value=msg(e)}finally{loading.value=false}}async function receive(x:Tarea){if(!confirm(`¿Recibir la tarea #${x.id}?`))return;receiving.value=x.id;try{await recibirTarea(x.id,'medicion');success.value='Tarea recibida correctamente.';await load(filters.page)}catch(e){error.value=msg(e)}finally{receiving.value=0}}function clear(){Object.assign(filters,{criterio:'',distrito_id:0,tipo_atencion_id:0});load()}function msg(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Medición / Tareas</nav><header class="hero"><div class="mark">TA</div><div><small>EVAN · MEDICIÓN</small><h1>Tareas por recibir</h1><p>Solicitudes comerciales derivadas al área de medición.</p></div><strong>{{total}} pendientes</strong></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash bad">{{error}}</p><section class="filters"><label>Ticket o tarea<input v-model.trim="filters.criterio" placeholder="Número" @keyup.enter="load()"></label><label>Distrito<select v-model.number="filters.distrito_id"><option :value="0">Todos</option><option v-for="x in districts" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Tipo de atención<select v-model.number="filters.tipo_atencion_id"><option :value="0">Todos</option><option v-for="x in types" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><div><button @click="load()">Consultar</button><button class="clear" @click="clear">Limpiar</button></div></section><div v-if="loading" class="empty">Cargando tareas de Medición…</div><div v-else-if="!rows.length" class="empty">No existen tareas pendientes de recepción.</div><section v-else class="cards"><article v-for="x in rows" :key="x.id"><header><b>Tarea #{{x.id}}</b><span>{{x.estado}}</span></header><h2>{{x.tipo_tarea}}</h2><p>{{x.descripcion||'Sin indicaciones adicionales.'}}</p><dl><div><small>Ticket</small><b>#{{x.ticket_id}}</b></div><div><small>Atención</small><b>{{x.tipo_atencion}}</b></div><div><small>Cliente</small><b>{{x.cliente}}</b></div><div><small>Distrito</small><b>{{x.distrito}}</b></div><div class="wide"><small>Dirección</small><b>{{x.direccion||'—'}}</b></div><div><small>Remitente</small><b>{{x.usuario_envia}}</b></div></dl><footer><span>{{x.fecha}}</span><button :disabled="receiving===x.id" @click="receive(x)">{{receiving===x.id?'Recibiendo…':'Recibir tarea'}}</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer></div></template>
<style scoped>
.page{--a:#397d8c;color:#37464d}nav{margin-bottom:16px;color:#96a0a5;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:800}.hero small{color:var(--a);font-size:.52rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.28rem}.hero p{margin:0;color:#7c898f;font-size:.62rem}.hero strong{margin-left:auto;font-size:.52rem}.flash{padding:10px;font-size:.6rem}.good{color:#267359;background:#eaf8f1}.bad{color:#a13e43;background:#fff0f0}.filters{margin-top:12px;padding:12px;display:grid;grid-template-columns:1fr 1fr 1.3fr auto;align-items:end;gap:8px;background:#fff}.filters label{font-size:.47rem}input,select{width:100%;padding:8px;border:1px solid #d7e0e3;border-radius:5px;font:inherit;font-size:.52rem}.filters button,.pages button{padding:8px 10px;border:0;border-radius:5px;color:#fff;background:var(--a);font-size:.47rem}.filters .clear{margin-left:4px;color:#68767c;background:#edf1f2}.cards{margin-top:12px;display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.cards article{padding:13px;display:flex;flex-direction:column;border-top:4px solid var(--a);border-radius:8px;background:#fff}.cards article>header{display:flex;justify-content:space-between;font-size:.5rem}.cards header span{padding:4px 7px;border-radius:9px;color:var(--a);background:#edf5f6;font-size:.4rem}.cards h2{margin:10px 0 3px;font-size:.68rem}.cards>article>p{min-height:28px;margin:0;color:#78858b;font-size:.47rem}.cards dl{display:grid;grid-template-columns:1fr 1fr;gap:7px}.cards dl small,.cards dl b{display:block;font-size:.43rem}.cards dl small{color:#8c979c}.cards .wide{grid-column:span 2}.cards footer{margin-top:auto;padding-top:9px;display:flex;align-items:center;justify-content:space-between;border-top:1px solid #e8ecee}.cards footer span{font-size:.4rem}.cards footer button{padding:7px 10px;border:0;border-radius:4px;color:#fff;background:var(--a);font-size:.46rem}.empty{margin-top:12px;padding:45px;text-align:center;background:#fff;font-size:.58rem}.pages{display:flex;justify-content:center;align-items:center;gap:8px;font-size:.48rem}@media(max-width:850px){.cards,.filters{grid-template-columns:1fr 1fr}}@media(max-width:540px){.hero{flex-wrap:wrap}.hero strong{margin-left:0}.cards,.filters{grid-template-columns:1fr}}
</style>
